def add_ssh_key(self, name, ssh_pub_key):
        """
        This method allows you to add a new public SSH key to your account.

        Required parameters

            name:
                String, the name you want to give this SSH key.

            ssh_pub_key:
                String, the actual public SSH key.
        """
        if not isinstance(ssh_pub_key, str):
            raise ValueError('ssh_pub_key must be a string')

        if not isinstance(name, str):
            raise ValueError('name must be a string')

        data = {
            'name': name,
            'ssh_pub_key': ssh_pub_key
        }

        return self._post('/api/2.0/sshkeys/', data)

